import pytest
from email_validator import is_valid_email  # Assuming the function is saved in email_validator.py


class TestIsValidEmail:
    """Test suite for is_valid_email function."""

    # Happy path tests
    class TestHappyPath:
        def test_standard_email(self):
            """Test a standard valid email address."""
            assert is_valid_email("user@example.com") is True

        def test_email_with_subdomain(self):
            """Test email with subdomain."""
            assert is_valid_email("user@mail.example.com") is True

        def test_email_with_plus_sign(self):
            """Test email with plus sign in local part."""
            assert is_valid_email("user+tag@example.com") is True

        def test_email_with_dots_in_local_part(self):
            """Test email with dots in the local part."""
            assert is_valid_email("first.last@example.com") is True

        def test_email_starting_with_number(self):
            """Test email starting with a number."""
            assert is_valid_email("123user@example.com") is True

        def test_email_with_hyphen_in_domain(self):
            """Test email with hyphen in domain name."""
            assert is_valid_email("user@my-domain.com") is True

        def test_various_valid_tlds(self):
            """Test emails with various valid TLDs."""
            valid_tlds = ["com", "org", "net", "io", "dev", "co"]
            for tld in valid_tlds:
                assert is_valid_email(f"user@example.{tld}") is True

        def test_email_case_insensitive_local(self):
            """Test email with uppercase letters."""
            assert is_valid_email("User@Example.Com") is True

    # Edge case tests
    class TestEdgeCases:
        def test_single_character_local(self):
            """Test email with single character local part."""
            assert is_valid_email("a@example.com") is True

        def test_long_local_part(self):
            """Test email with long local part."""
            long_local = "a" * 64 + "@example.com"
            assert is_valid_email(long_local) is True

        def test_email_with_underscore(self):
            """Test email with underscore in local part."""
            assert is_valid_email("user_name@example.com") is True

        def test_email_with_percent(self):
            """Test email with percent sign in local part."""
            assert is_valid_email("user%name@example.com") is True

        def test_dot_before_at_symbol(self):
            """Test email with dot immediately before @ symbol (valid per regex)."""
            assert is_valid_email("user.@example.com") is True

        def test_dot_after_at_symbol_start(self):
            """Test email with dot at start of domain (valid per regex)."""
            assert is_valid_email("user@.example.com") is True

    # Error case tests
    class TestErrorCases:
        def test_missing_at_symbol(self):
            """Test email without @ symbol."""
            assert is_valid_email("userexample.com") is False

        def test_missing_local_part(self):
            """Test email with just @ domain."""
            assert is_valid_email("@example.com") is False

        def test_missing_domain(self):
            """Test email without domain."""
            assert is_valid_email("user@") is False

        def test_missing_tld(self):
            """Test email without TLD."""
            assert is_valid_email("user@example") is False

        def test_empty_string(self):
            """Test empty string input."""
            assert is_valid_email("") is False

        def test_just_at_symbol(self):
            """Test string with just @ symbol."""
            assert is_valid_email("@") is False

        def test_double_at_symbol(self):
            """Test email with double @ symbols."""
            assert is_valid_email("user@@example.com") is False

        def test_space_in_email(self):
            """Test email with spaces."""
            assert is_valid_email("user name@example.com") is False

        def test_space_before_at(self):
            """Test email with space before @."""
            assert is_valid_email("user @example.com") is False

        def test_space_after_at(self):
            """Test email with space after @."""
            assert is_valid_email("user@ example.com") is False

        def test_multiple_dots_in_tld(self):
            """Test email with multiple dots in TLD (more than one level)."""
            # Pattern allows [a-zA-Z]{2,} for TLD which is single or multi-char TLD
            # but doesn't allow dots. So this should fail.
            assert is_valid_email("user@example.c.o.m") is False

        def test_invalid_characters(self):
            """Test email with special characters not allowed."""
            invalid_chars = ["user!name@example.com", "user#name@example.com", 
                             "user$name@example.com", "user&name@example.com",
                             "user=name@example.com", "user?name@example.com",
                             "user/name@example.com"]
            for email in invalid_chars:
                assert is_valid_email(email) is False

        def test_leading_dot_in_local(self):
            """Test email starting with dot in local part."""
            assert is_valid_email(".user@example.com") is False

        def test_consecutive_dots(self):
            """Test email with consecutive dots in local part."""
            assert is_valid_email("user..name@example.com") is False

        def test_no_domain_extension(self):
            """Test email without domain extension (single level domain)."""
            assert is_valid_email("user@example") is False

        def test_only_tld(self):
            """Test email with just TLD as domain."""
            assert is_valid_email("user@com") is False

        def test_newline_in_email(self):
            """Test email containing newline character."""
            assert is_valid_email("user@\nexample.com") is False

        def test_none_input(self):
            """Test None as input."""
            with pytest.raises(TypeError):
                is_valid_email(None)

        def test_non_string_input(self):
            """Test non-string input raises TypeError."""
            with pytest.raises(TypeError):
                is_valid_email(12345)

        def test_integer_input(self):
            """Test integer as input."""
            with pytest.raises(TypeError):
                is_valid_email(123)

        def test_list_input(self):
            """Test list as input."""
            with pytest.raises(TypeError):
                is_valid_email(["user@example.com"])
